import{_ as r,C as o,o as s,c as l,a2 as i,j as a,a as t,E as d}from"./chunks/framework.Di-jvWLj.js";const v=JSON.parse('{"title":"Multiple Replicas","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/replicas.md","filePath":"deployment/replicas.md","lastUpdated":1793088333000}'),c={name:"deployment/replicas.md"},p={id:"what-still-needs-planned-packages",tabindex:"-1"};function h(u,e,g,m,y,k){const n=o("Badge");return s(),l("div",null,[e[3]||(e[3]=i('<h1 id="multiple-replicas" tabindex="-1">Multiple Replicas <a class="header-anchor" href="#multiple-replicas" aria-label="Permalink to &quot;Multiple Replicas&quot;">​</a></h1><p>Running more than one replica of an agent app relies on the store. Core, the TypeORM store and <code>@chamvi/channel-cron</code> cover this today; part needs planned packages.</p><h2 id="what-core-already-guarantees" tabindex="-1">What core already guarantees <a class="header-anchor" href="#what-core-already-guarantees" aria-label="Permalink to &quot;What core already guarantees&quot;">​</a></h2><p>With a shared, durable store such as the <a href="/stores/typeorm">TypeORM store</a> (<code>MemoryStore</code> cannot be shared), several <code>Engine</code>s coordinate without a leader:</p><ul><li><strong>One executor per run.</strong> Run claims are leases (<code>claimTtlMs</code>, renewed every third of it). A replica that loses its lease stops writing.</li><li><strong>One run per concurrency key.</strong> Checked under a store lock, across replicas.</li><li><strong>One run per idempotency key.</strong> <code>dispatch()</code> claims the key atomically; redeliveries to any replica return the same run.</li><li><strong>Crash recovery.</strong> Every replica&#39;s poll requeues runs whose claim expired, and the next execution continues from the latest checkpoint.</li><li><strong>Graceful drain.</strong> A terminating pod marks its unfinished runs <code>interrupted</code> and another replica picks them up.</li><li><strong>Cross-replica cancel.</strong> <code>cancel()</code> on any replica reaches the run&#39;s owner on its next poll.</li><li><strong>One approval message.</strong> A store lock per approval plus the message key (<code>&lt;runId&gt;:&lt;approvalId&gt;</code>) the channel dedupes on; a tool&#39;s <code>emit()</code> is recorded as an effect, so a redone step sends once.</li><li><strong>Cron once per tick.</strong> The cron channel (<a href="/guide/scheduler"><code>@chamvi/channel-cron</code></a>) takes a store lock per subscription and scheduled time (never released, so a late replica cannot fire the same tick again) and dispatches with an idempotency key built from the same pair. <code>engine.drain()</code> stops it before draining the runs.</li></ul><p>Give each replica a distinct <code>owner</code> (the default <code>&lt;hostname&gt;-&lt;pid&gt;</code> already is in Kubernetes). See <a href="/guide/concurrency">Concurrency, Leases &amp; Multi-Replica</a>.</p>',6)),a("h2",p,[e[0]||(e[0]=t("What still needs planned packages ",-1)),d(n,{type:"warning",text:"Planned"}),e[1]||(e[1]=t()),e[2]||(e[2]=a("a",{class:"header-anchor",href:"#what-still-needs-planned-packages","aria-label":'Permalink to "What still needs planned packages <Badge type="warning" text="Planned" />"'},"​",-1))]),e[4]||(e[4]=a("ul",null,[a("li",null,[a("strong",null,"Webhooks to any replica."),t(" The planned HTTP app acknowledges webhooks with "),a("code",null,"202"),t(" and the run id, and uses the delivery id as the idempotency key, so a redelivery to another replica is deduplicated.")])],-1)),e[5]||(e[5]=a("p",null,[t("The planned Helm chart defaults to one replica with the "),a("code",null,"Recreate"),t(" strategy. Raising the replica count is safe once the store is shared.")],-1))])}const w=r(c,[["render",h]]);export{v as __pageData,w as default};
